def set_kv_upstash(key: str, value: str, ttl: Optional[int] = None):
    base = os.environ.get("UPSTASH_REDIS_REST_URL")
    token = os.environ.get("UPSTASH_REDIS_REST_TOKEN")
    headers = {"Authorization": f"Bearer {token}", "Content-Type": "application/json"}
    data = {"key": key, "value": value}
    if ttl is not None:
        data["ttl"] = ttl
    requests.post(f"{base}/set", headers=headers, json=data, timeout=30)

def get_kv_upstash(key: str) -> Optional[str]:
    base = os.environ.get("UPSTASH_REDIS_REST_URL")
    token = os.environ.get("UPSTASH_REDIS_REST_TOKEN")
    headers = {"Authorization": f"Bearer {token}", "Content-Type": "application/json"}
    r = requests.post(f"{base}/get", headers=headers, json={"key": key}, timeout=30)
    if r.status_code == 200:
        j = r.json()
        return j.get("result")
    return None

def emit(job_id: str, event_type: str, data: Dict[str, Any]):
    payload = {"ts": now_iso(), "type": event_type, "data": data}
