    except Exception:
        pass
    try:
        r = get_primary_redis()
        r.rpush(CONFIG["storage"]["redis_db_prefix"] + f"{job_id}:events", json.dumps(payload))
        r.expire(CONFIG["storage"]["redis_db_prefix"] + f"{job_id}:events", CONFIG["storage"]["job_ttl_seconds"])
    except Exception:
        pass

def set_state(job_id: str, state: Dict[str, Any]):
