        r = get_primary_redis()
        r.hset(CONFIG["storage"]["redis_db_prefix"] + f"{job_id}:state", mapping={k: json.dumps(v) for k, v in state.items()})
        r.expire(CONFIG["storage"]["redis_db_prefix"] + f"{job_id}:state", CONFIG["storage"]["job_ttl_seconds"])
    except Exception:
        pass
    try:
        set_kv_upstash(CONFIG["storage"]["redis_db_prefix"] + f"{job_id}:state_backup", json.dumps(state), CONFIG["storage"]["job_ttl_seconds"])
    except Exception:
        pass

def get_state(job_id: str) -> Dict[str, Any]:
    out = {}
