        r = get_primary_redis()
        d = r.hgetall(CONFIG["storage"]["redis_db_prefix"] + f"{job_id}:state")
        for k, v in d.items():
            try:
                out[k] = json.loads(v)
            except Exception:
                out[k] = v
    except Exception:
        pass
    if not out:
        try:
            backup = get_kv_upstash(CONFIG["storage"]["redis_db_prefix"] + f"{job_id}:state_backup")
            if backup:
                out = json.loads(backup)
        except Exception:
            pass
    return out

