def cerebras_client() -> Cerebras:
    if Cerebras is None:
        raise RuntimeError("Cerebras SDK missing")
    api_key = os.environ.get("CEREBRAS_API_KEY")
    if not api_key:
        raise RuntimeError("CEREBRAS_API_KEY not set")
