def bedrock_client() -> AnthropicBedrock:
    if AnthropicBedrock is None:
        raise RuntimeError("AnthropicBedrock SDK missing")
    key = os.environ.get("BEDROCK_API_KEY")
    region = os.environ.get("AWS_REGION", "us-east-1")
    if not key:
        raise RuntimeError("BEDROCK_API_KEY not set")
    return AnthropicBedrock(aws_access_key=key, aws_region=region)

def grok_chat(messages: List[Dict[str, str]], max_tokens: int, temperature: float, stream: bool = False):
    api_key = os.environ.get("GROK_API_KEY")
    if not api_key:
        raise RuntimeError("GROK_API_KEY not set")
    headers = {"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"}
    payload = {
        "model": CONFIG["models"]["writer_model_grok"],
        "messages": messages,
        "max_tokens": max_tokens,
        "temperature": temperature,
        "stream": stream
    }
    resp = requests.post("", headers=headers, json=payload, stream=stream, timeout=600)
    if resp.status_code != 200:
        raise RuntimeError(f"Grok error {resp.status_code}: {resp.text}")
    return resp

def unify_completion(messages: List[Dict[str, str]], provider: str, model: Optional[str] = None, max_tokens: Optional[int] = None, temperature: Optional[float] = None, stream: bool = False, response_format: Optional[Dict[str, Any]] = None):
    if provider == "cerebras":
        cli = cerebras_client()
        m = model or CONFIG["models"]["analysis_model_cerebras"]
        return cli.chat.completions.create(model=m, messages=messages, max_tokens=max_tokens or CONFIG["limits"]["max_tokens_cerebras"], temperature=temperature if temperature is not None else CONFIG["limits"]["temperature_default"], stream=stream, response_format=response_format)
    if provider == "bedrock":
        cli = bedrock_client()
        m = model or CONFIG["models"]["summary_model_bedrock"]
        sys_msg = None
        conv = []
        for msg in messages:
            if msg["role"] == "system":
                sys_msg = msg["content"]
            else:
                conv.append({"role": msg["role"], "content": msg["content"]})
        kwargs = {"model": m, "messages": conv, "max_tokens": max_tokens or 8192, "temperature": temperature if temperature is not None else CONFIG["limits"]["temperature_default"]}
        if sys_msg:
            kwargs["system"] = sys_msg
        res = cli.messages.create(**kwargs)
        class Choice:
            def __init__(self, c):
                self.message = type("obj", (object,), {"content": c})
                self.delta = type("obj", (object,), {"content": c})
        class Resp:
            def __init__(self, c):
                self.choices = [Choice(c)]
        return Resp(res.content[0].text)
    if provider == "grok":
        r = grok_chat(messages, max_tokens or CONFIG["limits"]["max_tokens_grok"], temperature if temperature is not None else CONFIG["limits"]["temperature_default"], stream=stream)
        if stream:
            return r
        data = r.json()
        class Choice:
            def __init__(self, c):
                self.message = type("obj", (object,), {"content": c})
                self.delta = type("obj", (object,), {"content": c})
        class Resp:
            def __init__(self, c):
                self.choices = [Choice(c)]
        return Resp(data["choices"][0]["message"]["content"])
    raise RuntimeError("Unknown provider")

def exa_search_full(query: str, num: int) -> Any:
    exa = exa_client()
    return exa.search_and_contents(query=query, type=CONFIG["exa"]["type"], num_results=min(num, CONFIG["agent"]["max_sources"]), text=CONFIG["exa"]["text"], highlights=CONFIG["exa"]["highlights"], livecrawl=CONFIG["exa"]["livecrawl"])

def exa_find_similar_full(url: str, num: int) -> Any:
    exa = exa_client()
