def exa_research_task(instructions: str, model: str = "exa-research-pro", output_schema: Optional[Dict[str, Any]] = None) -> str:
    exa = exa_client()
    t = exa.research.create_task(model=model, instructions=instructions, output_schema=output_schema or {"type": "object", "properties": {"findings": {"type": "array", "items": {"type": "string"}}}, "required": ["findings"]})
    return t.id if hasattr(t, "id") else t

def exa_research_poll(task_id: str, timeout_s: int = 1800) -> Any:
    exa = exa_client()
    start = time.time()
    while time.time() - start < timeout_s:
        r = exa.research.get_task(task_id)
        status = getattr(r, "status", None) or (r.get("status") if isinstance(r, dict) else None)
        if status in ("completed", "failed", "canceled"):
            return r
        time.sleep(3)
    return r

def clamp_len(s: str, n: int) -> str:
    return s if len(s) <= n else s[:n]

def generate_followups(topic: str, k: int) -> List[str]:
    sys_prompt = "Te egy stratégiai kutatási tervező vagy. Állíts össze célratörő, nem redundáns keresőkérdéseket, amelyek lefedik a témához tartozó altémákat, nézőpontokat, vitákat, adatsorokat és idővonalakat."
    user_prompt = f"Kérlek, készíts {k} darab célzott keresőkérdést a következő főtémához:\n\n{topic}\n\nKimenet JSON: {{\"queries\": [\"...\"]}}"
    res = unify_completion(
        [{"role": "system", "content": sys_prompt}, {"role": "user", "content": user_prompt}],
        provider="cerebras",
        model=CONFIG["models"]["planner_model_cerebras"],
        max_tokens=CONFIG["limits"]["max_tokens_cerebras"],
        temperature=0.4,
        stream=False,
        response_format={"type": "json_schema", "json_schema": {"name": "queries", "strict": True, "schema": {"type": "object", "properties": {"queries": {"type": "array", "items": {"type": "string"}}}, "required": ["queries"]}}}
    )
    try:
        j = json.loads(res.choices[0].message.content)
        qs = [q for q in j.get("queries", []) if isinstance(q, str) and q.strip()]
        return qs
    except Exception:
        return [topic]

def summarize_article(text: str, title: str, brief: Dict[str, Any]) -> str:
    reflection_prompt = f"Feladat: Foglald össze a cikket a kutatási cél alapján.\nCím: {title}\nKutatási rövid:\n{json.dumps(brief, ensure_ascii=False)}\nCikk (részlet):\n{clamp_len(text, 6000)}\nAdj vissza JSON-t: {{\"key_points\": [\"...\"], \"verdict\": \"...\"}}"
    ref = unify_completion([{"role": "user", "content": reflection_prompt}], provider="bedrock", max_tokens=8192, temperature=0.3)
    try:
        data = json.loads(ref.choices[0].message.content)
        key_points = data.get("key_points", [])
        verdict = data.get("verdict", "")
        if not isinstance(key_points, list):
            key_points = []
    except Exception:
        key_points = []
        verdict = ""
    if not key_points:
        return ""
    elaboration = f"Készíts gördülékeny, tényekben pontos, 2-4 bekezdéses magyar összefoglalót az alábbi kulcspontok alapján, a teljes cikkrészlet felhasználásával.\nKulcspontok:\n{json.dumps(key_points, ensure_ascii=False, indent=2)}\nCikk:\n{clamp_len(text, 6000)}\n"
    summ = unify_completion([{"role": "user", "content": elaboration}], provider="bedrock", max_tokens=8192, temperature=0.4)
    return summ.choices[0].message.content

def write_report_stream(sources: List[Dict[str, Any]], outline_hint: Optional[str], min_words: int, max_words: int):
    ctx_parts = []
    for i, s in enumerate(sources, 1):
        ctx_parts.append(f"Source {i} | {s.get('title','')}\n{s.get('url','')}\n---\n{clamp_len(s.get('summary',''), 4000)}\n")
    sys_prompt = textwrap.dedent(f"""
    Nagyléptékű oknyomozó újságíró és szerkesztő vagy. Írj teljes, magyar nyelvű, professzionális jelentést {min_words}-{max_words} szó terjedelemben az alábbi források alapján, Markdown formátumban, szekciócímekkel, narratív folyással és következetes hivatkozásjelöléssel [Source 1, 3] alakban.
    """).strip()
    user_prompt = "Forráskivonatok:\n\n" + "\n".join(ctx_parts) + ("\nElőzetes vázlat:\n" + outline_hint if outline_hint else "")
    messages = [{"role": "system", "content": sys_prompt}, {"role": "user", "content": user_prompt}]
    resp = grok_chat(messages, max_tokens=CONFIG["limits"]["max_tokens_grok"], temperature=0.5, stream=True)
    return resp

def normalize_citations(md_text: str, sources: List[Dict[str, Any]]) -> str:
    matches = re.findall(r"\[Source ([^\]]+)\]", md_text)
    if not matches:
        ref = "\n\n---\n\n## Hivatkozások\n"
        for i, s in enumerate(sources, 1):
            ref += f"{i}. {s.get('title','')} ({s.get('url','')})\n"
        return md_text + ref
    all_idx = set()
    for m in matches:
        parts = [p.strip() for p in m.split(",")]
        for p in parts:
            try:
                all_idx.add(int(p))
            except Exception:
                pass
    ordered = sorted(all_idx)
    cmap = {orig: i + 1 for i, orig in enumerate(ordered)}
    def repl(m):
        grp = m.group(1)
        nums = []
        for p in [x.strip() for x in grp.split(",")]:
            try:
                nums.append(cmap[int(p)])
            except Exception:
                pass
        nums = sorted(set(nums))
        return "[" + ", ".join(str(x) for x in nums) + "]"
    out = re.sub(r"\[Source ([^\]]+)\]", repl, md_text)
    ref = "\n\n---\n\n## Hivatkozások\n"
    for orig in ordered:
        newn = cmap[orig]
        s = sources[orig - 1] if 1 <= orig <= len(sources) else {}
        ref += f"{newn}. {s.get('title','')} ({s.get('url','')})\n"
    return out + ref

def agent_loop(job_id: str, topic: str, minutes: int):
    start = time.time()
    emit(job_id, "started", {"topic": topic, "max_minutes": minutes})
    set_state(job_id, {"status": "running", "topic": topic, "started": now_iso()})
    try:
        plan = unify_completion(
            [{"role": "system", "content": "Stratégiai kutatási tervező vagy. Bontsd fel a témát ütemekre, taktikákra, forrásfajtákra, hipotézisekre és ellenőrzési pontokra JSON formátumban."},
             {"role": "user", "content": f"Téma: {topic}\nAdj vissza JSON-t: {{\"phases\": [...], \"key_questions\": [...], \"risks\": [...], \"queries_seed\": [...]}}"}],
            provider="cerebras",
            model=CONFIG["models"]["planner_model_cerebras"],
            max_tokens=CONFIG["limits"]["max_tokens_cerebras"],
            temperature=0.3,
            stream=False
        )
        try:
            plan_json = json.loads(plan.choices[0].message.content)
        except Exception:
            plan_json = {"phases": [], "key_questions": [], "risks": [], "queries_seed": [topic]}
        emit(job_id, "plan", {"plan": plan_json})
        set_state(job_id, {"plan": plan_json})

        queries = plan_json.get("queries_seed") or []
        if not queries:
            queries = [topic]
        extra = generate_followups(topic, 12)
        queries = list(dict.fromkeys([q for q in (queries + extra) if isinstance(q, str) and q.strip()]))[:64]
        emit(job_id, "queries", {"count": len(queries)})

        all_results: List[Dict[str, Any]] = []
        summarized: List[Dict[str, Any]] = []

        def process_query(qs: List[str]):
            for qtext in qs:
                if time.time() - start > minutes * 60 or stop_flags[job_id].is_set():
                    return
                emit(job_id, "search_start", {"query": qtext})
                try:
                    sr = exa_search_full(qtext, CONFIG["exa"]["num_results"])
                    rs = []
                    for r in sr.results:
                        rs.append({
                            "url": getattr(r, "url", None),
                            "title": getattr(r, "title", None),
                            "id": getattr(r, "id", None),
                            "published_date": getattr(r, "published_date", None),
                            "text": getattr(r, "text", None),
                            "highlights": getattr(r, "highlights", None)
                        })
                    all_results.extend(rs)
                    emit(job_id, "search_done", {"query": qtext, "results": len(rs)})
                except Exception as e:
                    emit(job_id, "error", {"stage": "search", "query": qtext, "error": str(e)})
                    continue

        threads = []
        chunk_size = max(1, len(queries) // max(1, min(len(queries), CONFIG["agent"]["max_parallel_fetch"])))
        for i in range(0, len(queries), chunk_size):
            t = threading.Thread(target=process_query, args=(queries[i:i + chunk_size],), daemon=True)
            threads.append(t)
            t.start()
        for t in threads:
            t.join()

        uniq = {}
        for r in all_results:
            u = r.get("url")
            if u and u not in uniq:
                uniq[u] = r
        base_results = list(uniq.values())[:CONFIG["agent"]["max_sources"]]
        emit(job_id, "dedup", {"kept": len(base_results)})

        for i, r in enumerate(base_results, 1):
            if time.time() - start > minutes * 60 or stop_flags[job_id].is_set():
                break
            url = r.get("url") or ""
            title = r.get("title") or ""
            text = r.get("text") or ""
            brief = {"topic": topic, "url": url}
            summ = ""
            try:
                if not text:
                    try:
                        sim = exa_find_similar_full(url, 5)
                        for rx in sim.results:
                            if getattr(rx, "text", None):
                                text = rx.text
                                break
                    except Exception:
                        pass
                if text:
                    summ = summarize_article(text, title or url, brief)
            except Exception as e:
                emit(job_id, "error", {"stage": "summarize", "url": url, "error": str(e)})
            summarized.append({"url": url, "title": title or url, "summary": summ or "", "highlights": r.get("highlights")})
            emit(job_id, "article", {"index": i, "title": title or url})

        set_state(job_id, {"sources": summarized})

        task_id = ""
        try:
            task_id = exa_research_task(f"Készíts mély kutatási kivonatot és strukturált megállapításokat a témához: {topic}. Adj ki JSON-t szekciókkal, kulcskérdésekkel és hivatkozási javaslatokkal.")
            emit(job_id, "research_task", {"task_id": task_id})
        except Exception as e:
            emit(job_id, "error", {"stage": "exa_research_create", "error": str(e)})

        exa_result = None
        if task_id:
            try:
                exa_result = exa_research_poll(task_id, timeout_s=1800)
                emit(job_id, "research_result", {"status": getattr(exa_result, "status", "done")})
            except Exception as e:
                emit(job_id, "error", {"stage": "exa_research_poll", "error": str(e)})

        outline_hint = None
        try:
            context = ""
            for i, s in enumerate(summarized[:40], 1):
                context += f"--- Source {i} ---\nTitle: {s.get('title','')}\nURL: {s.get('url','')}\nSummary:\n{clamp_len(s.get('summary',''), 1200)}\n\n"
            sys_msg = "Szerkesztő vagy. Készíts részletes vázlatot fejezetcímekkel, kulcspontokkal és hivatkozási indexekkel JSON formátumban."
            user_msg = "Források kivonatai:\n\n" + context + "\nAdj vissza JSON-t: {\"title\": \"...\", \"sections\": [{\"heading\": \"...\", \"bullets\": [{\"text\": \"...\", \"sources\": [1,2]}]}], \"conclusion\": \"...\"}"
            outline = unify_completion(
                [{"role": "system", "content": sys_msg}, {"role": "user", "content": user_msg}],
                provider="bedrock",
                max_tokens=8192,
                temperature=0.4
            )
            outline_hint = outline.choices[0].message.content
            emit(job_id, "outline", {"ok": True})
        except Exception as e:
            emit(job_id, "error", {"stage": "outline", "error": str(e)})

        resp = write_report_stream(summarized, outline_hint, CONFIG["agent"]["report_min_words"], CONFIG["agent"]["report_max_words"])
        full_text = ""
        for ln in resp.iter_lines():
            if stop_flags[job_id].is_set():
                break
            if not ln:
                continue
            try:
                line = ln.decode("utf-8")
            except Exception:
                continue
            if line.startswith("data: "):
                data_str = line[6:]
                if data_str.strip() == "[DONE]":
                    break
                try:
                    data = json.loads(data_str)
                    if "choices" in data and data["choices"]:
                        delta = data["choices"][0].get("delta", {})
                        if "content" in delta:
                            chunk = delta["content"]
                            full_text += chunk
                            emit(job_id, "report_chunk", {"n": len(chunk)})
                except Exception:
                    pass

        full_text = normalize_citations(full_text, summarized)
        save_blob(job_id, "report.md", full_text)
        set_state(job_id, {"status": "completed", "finished": now_iso(), "report_key": f"{CONFIG['storage']['redis_db_prefix']}{job_id}:blob:report.md"})
        emit(job_id, "completed", {"bytes": len(full_text)})

    except Exception as e:
        err = {"error": str(e), "trace": traceback.format_exc()}
        set_state(job_id, {"status": "failed", "error": err})
        emit(job_id, "failed", err)

